export function interpretRuneSpread(spreadDef:RuneSpread,drawn:RuneMeaning[],language:Language="ES"):RuneReading{
 const misc=RUNE_MISC_T[language]||RUNE_MISC_T.ES;
 if(drawn.length<spreadDef.positions.length)throw new Error(misc.requires(spreadDef.name,spreadDef.positions.length));
 const relations=spreadDef.positions.slice(0,-1).map((position,index)=>({id:`rune-relation:${spreadDef.id}:${index+1}`,from:position.id,to:spreadDef.positions[index+1].id,type:relationType(position,spreadDef.positions[index+1])}));
 const positionAnswers:RunePositionAnswer[]=spreadDef.positions.map((position,index)=>{const rune=drawn[index];return {positionId:position.id,position:position.label,role:position.role,runeId:rune.id,runeName:rune.name,answer:positionBody(rune,position,language),rune,sourceRuneIds:[rune.id],sourcePositionIds:[position.id],sourceRelationIds:relations.filter(relation=>relation.from===position.id||relation.to===position.id).map(relation=>relation.id)}});
 const verdict=spreadDef.id==="reasoned"?runeVerdict(positionAnswers,language):undefined,sections=runeEditorialSections(spreadDef,positionAnswers,verdict,language);
 for(const section of sections)section.sourceRelationIds=relations.filter(relation=>section.sourcePositionIds.includes(relation.from)&&section.sourcePositionIds.includes(relation.to)).map(relation=>relation.id);
 const story=sections.map(item=>item.body),main=story.join(" "),riskAnswer=positionAnswers.find(item=>item.role==="risk"||item.role==="obstacle"||item.role==="shadow")||positionAnswers.find(item=>item.rune.tone==="restrictive"),actionAnswer=positionAnswers.find(item=>item.role==="action"||item.role==="advice")||positionAnswers.find(item=>item.rune.tone==="supportive"),rawCaution=(riskAnswer?translateRune(riskAnswer.rune,language).risk:undefined)||misc.defaultCaution,rawAdvice=actionAnswer?`${translateRune(actionAnswer.rune,language).resource} ${translateRune(actionAnswer.rune,language).action}`:misc.defaultAdvice;
 const caution=semanticOverlap(rawCaution,main)>.46?"":sentence(rawCaution),advice=semanticOverlap(rawAdvice,main)>.46||semanticOverlap(rawAdvice,caution)>.38?"":sentence(rawAdvice),sourceRuneIds=unique(positionAnswers.map(item=>item.runeId)),sourcePositionIds=unique(positionAnswers.map(item=>item.positionId)),sourceRelationIds=unique(relations.map(item=>item.id));
 const summary=`${verdict?`${verdict}. `:""}${sections[0].body}${sections.length>1?` ${sections.at(-1)!.body}`:""}`;
 const title=verdict?misc.titles.reasoned:spreadDef.id==="feel-think-act"?misc.titles.feelThinkAct:spreadDef.id==="two-paths"||spreadDef.id==="act-or-not"?misc.titles.comparison:spreadDef.id==="opportunity-risk-strategy"?misc.titles.opportunity:spreadDef.id==="shadow-learning-resource"?misc.titles.shadowLearning:spreadDef.id==="rune-cross-nine"?misc.titles.crossNine:spreadDef.positions.length>7?misc.titles.longStory:misc.titles.defaultTitle;
 return {title,sections,positionAnswers,story,summary,verdict,warning:caution||rawCaution,showWarning:Boolean(caution),warningTitle:misc.warningTitle,caution,showAdvice:Boolean(advice),adviceTitle:misc.adviceTitle,advice,narrativeSynthesis:{readingThesis:sections[0]?.body||"",mainMovement:sections.at(-1)?.body||"",sourceRuneIds,sourcePositionIds,sourceRelationIds},debug:{spreadId:spreadDef.id,relations}};
}

