const VERDICT_HEXAGRAM_T={
 ES:{favorable:"Favorable",wait:"Conviene esperar",adverse:"Desfavorable por ahora",other:"Favorable con condiciones"},
 EN:{favorable:"Favorable",wait:"Better to wait",adverse:"Unfavorable for now",other:"Favorable with conditions"},
 FR:{favorable:"Favorable",wait:"Mieux vaut attendre",adverse:"Défavorable pour l'instant",other:"Favorable sous conditions"},
 DE:{favorable:"Günstig",wait:"Warten ist ratsam",adverse:"Vorerst ungünstig",other:"Günstig unter Bedingungen"},
 PT:{favorable:"Favorável",wait:"Convém esperar",adverse:"Desfavorável por enquanto",other:"Favorável com condições"},
};
const verdictForHexagram=(number:number,language:Language="ES")=>{
 const T=VERDICT_HEXAGRAM_T[language]||VERDICT_HEXAGRAM_T.ES;
 return favorable.has(number)?T.favorable:waitSet.has(number)?T.wait:adverse.has(number)?T.adverse:T.other;
};
export const getIChingCounsel=(number:number,language:Language="ES")=>{
 if(language==="ES")return hexagramCounsel[number-1]||"Observa el cambio y responde con medida.";
 return HEXAGRAM_COUNSEL_T[language]?.[number-1]||hexagramCounsel[number-1]||"Observa el cambio y responde con medida.";
};
