 if(consultation.id==="relationship")return [section("bond","Dynamic of the bond",`${present} Between the two of you, this calls for visible reciprocity, not just intention.`,[primary.number]),section("care","What needs care",`${hidden} ${risk}.`,[primary.number,nuclear.number],changingLines),section("direction","Resulting direction",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
