function ichingEditorialSectionsPT(consultation:IChingConsultation,primary:typeof ichingCatalog[number],transformed:typeof ichingCatalog[number],nuclear:typeof ichingCatalog[number],changingLines:number[],verdict:string,counsel:string,resultCounsel:string,nuclearCounsel:string):IChingSection[]{
 const changed=primary.number!==transformed.number;
 const lineFocus=changingLines.length?`O movimento se concentra em ${changingLines.map(number=>phaseByLine("PT")[number-1]).join(" e ")}`:"Não há linhas mutantes: a situação não pede outro giro, mas sim sustentar e verificar a orientação presente";
 const consequence=changed?`Se você fizer esse ajuste, o processo pode tomar a forma de ${transformed.name}: ${lowerFirst(resultCounsel)}`:`Se você mantiver esse critério, ${primary.name} pode se consolidar; mudar de resposta por impaciência romperia essa continuidade`;
 const present=`${primary.name} descreve o momento visível: ${lowerFirst(counsel)}`;
 const hidden=`Por baixo opera ${nuclear.name}. Isso indica que não basta atender ao evidente: ${lowerFirst(nuclearCounsel)}`;
 const risk=`A dificuldade aparece se você acaba por ${hexagramRisk(primary.number,"PT")}`;
 const section=(id:string,title:string,body:string,hexagrams:number[],lines:number[]=[])=>ichingSection(consultation,id,title,body,hexagrams,lines);
 if(consultation.id==="reasoned")return [section("orientation","Orientação",`${verdict}. ${present}`,[primary.number]),section("why","Por quê",`${hidden} ${lineFocus}.`,[primary.number,nuclear.number],changingLines),section("condition","Condição",`A resposta só se sustenta se você transformar o conselho em uma conduta verificável. ${consequence}`,[primary.number,transformed.number],changingLines),section("warning","Advertência",`${risk}. Não tome o veredicto como permissão para ignorar essa condição.`,[primary.number]),section("direction","Direção resultante",consequence,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="two-options")return [section("aligned","A alternativa que se alinha",`${primary.name} favorece a opção que permite ${lowerFirst(counsel)} e que responde à necessidade interna de ${nuclear.name}.`,[primary.number,nuclear.number]),section("misaligned","A alternativa que acumula atrito",`A outra opção perde força se exigir ${hexagramRisk(primary.number,"PT")}. ${lineFocus}.`,[primary.number],changingLines),section("comparison","Comparação",`Não compare apenas o que você deseja mais; observe o que você pode sustentar com fatos e recursos reais. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="relationship")return [section("bond","Dinâmica do vínculo",`${present} Entre vocês dois, isso pede reciprocidade visível, não apenas intenção.`,[primary.number]),section("care","O que precisa de cuidado",`${hidden} ${risk}.`,[primary.number,nuclear.number],changingLines),section("direction","Direção resultante",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="work")return [section("conditions","Condições do projeto",`${present} Este é o critério com o qual convém ordenar responsabilidades, prazos e recursos.`,[primary.number]),section("change","O que está mudando",`${hidden} ${lineFocus}.`,[primary.number,nuclear.number],changingLines),section("strategy","Estratégia prática",`Faça primeiro o ajuste que você pode verificar e evite comprometer mais recursos antes de comprovar seu efeito. ${risk}.`,[primary.number,nuclear.number]),section("direction","Direção resultante",consequence,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="money")return [section("block","A restrição",`${present} O bloqueio aumenta quando você acaba por ${hexagramRisk(primary.number,"PT")}.`,[primary.number]),section("movement","Movimento possível",`${hidden} Reordene primeiro o essencial e verifique o resultado antes de assumir uma obrigação maior.`,[primary.number,nuclear.number],changingLines),section("direction","Direção resultante",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="support-obstacle")return [section("support","O que favorece",`${present} A seu favor está qualquer apoio, hábito ou acordo que permita agir dessa maneira.`,[primary.number]),section("obstacle","O que dificulta",`${hidden} ${risk}.`,[primary.number,nuclear.number]),section("direction","O ajuste necessário",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="act")return [section("present","O que já está acontecendo",`${present} ${hidden}`,[primary.number,nuclear.number]),section("action","Se você intervier",`Agir só faz sentido se você puder ${lowerFirst(counsel)}. Se você intervier por urgência, corre o risco de ${hexagramRisk(primary.number,"PT")}.`,[primary.number]),section("direction","A consequência provável",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="wait")return [section("present","O que já está acontecendo",`${present} ${hidden}`,[primary.number,nuclear.number]),section("waiting","Se você esperar",`Esperar ajuda apenas se você usar o tempo para preparar condições, corrigir erros ou reunir recursos. Uma espera passiva conservará o problema sem aproximá-lo de ${transformed.name}.`,[primary.number,transformed.number]),section("direction","A consequência provável",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="reconciliation")return [section("conflict","O que mantém a tensão",`${present} O conflito persiste quando uma parte insiste em ${hexagramRisk(primary.number,"PT")}.`,[primary.number]),section("repair","O que poderia repará-lo",`${hidden} Reparar exige uma conduta diferente e verificável, não apenas uma conversa tranquilizadora.`,[primary.number,nuclear.number]),section("direction","A direção do vínculo",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="personal")return [section("identity","O que está mudando em você",`${present} ${hidden}`,[primary.number,nuclear.number]),section("integration","Como integrá-lo",`${lineFocus}. Leve essa compreensão a uma decisão, um limite ou um hábito concreto; caso contrário, continuará sendo apenas uma ideia.`,[primary.number,nuclear.number],changingLines),section("direction","A etapa que pode se abrir",consequence,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="transition")return [section("threshold","O limiar",`${present} Já não convém responder como se as condições anteriores continuassem intactas.`,[primary.number]),section("risk","O que pode complicar a travessia",`${hidden} ${risk}.`,[primary.number,nuclear.number]),section("direction","Como atravessá-lo",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
 if(consultation.id==="deep")return [section("present","Como você chegou a este ponto",`${present} Esta figura mostra a condição dominante, mas não explica sozinha todo o processo.`,[primary.number]),section("inner","O que opera por baixo",hidden,[primary.number,nuclear.number]),section("change","O ponto decisivo",`${lineFocus}. Aqui se define se o processo avança ou repete sua tensão.`,[primary.number,transformed.number],changingLines),section("direction","A direção provável",`${consequence} Se você não fizer esse ajuste, o risco é ${hexagramRisk(primary.number,"PT")}.`,[primary.number,transformed.number],changingLines)];
 return [section("present","O que este momento exige",present,[primary.number]),section("inner","O que ocorre por baixo",hidden,[primary.number,nuclear.number]),section("direction","A direção prática",`${lineFocus}. ${consequence}`,[primary.number,transformed.number],changingLines)];
}

export function castIChing(random=()=>Math.random()):IChingLine[]{
 return Array.from({length:6},()=>{const value=(Array.from({length:3},()=>random()<.5?2:3).reduce((sum,item)=>sum+item,0)) as 6|7|8|9;return {value,yang:value===7||value===9,changing:value===6||value===9};});
}

