export function interpretIChing(consultation:IChingConsultation,lines:IChingLine[],language:Language="ES"):IChingReading{
 const primaryPattern=[...lines].reverse().map(line=>line.yang?"1":"0").join(""),transformedPattern=[...lines].reverse().map(line=>(line.changing?!line.yang:line.yang)?"1":"0").join("");
 const nuclearBottom=[lines[1].yang,lines[2].yang,lines[3].yang,lines[2].yang,lines[3].yang,lines[4].yang],nuclearPattern=[...nuclearBottom].reverse().map(value=>value?"1":"0").join("");
 const rawPrimary=ichingCatalog.find(item=>item.pattern===primaryPattern)!,rawTransformed=ichingCatalog.find(item=>item.pattern===transformedPattern)!,rawNuclear=ichingCatalog.find(item=>item.pattern===nuclearPattern)!,changingLines=lines.map((line,index)=>line.changing?index+1:0).filter(Boolean),verdict=verdictForHexagram(rawPrimary.number,language),counsel=getIChingCounsel(rawPrimary.number,language),resultCounsel=getIChingCounsel(rawTransformed.number,language),nuclearCounsel=getIChingCounsel(rawNuclear.number,language);
 const localizeHexagram=<T extends {name:string}>(hexagram:T):T=>language==="ES"?hexagram:{...hexagram,name:translateIChingHexagram(hexagram.name,language)};
 const primary=localizeHexagram(rawPrimary),transformed=localizeHexagram(rawTransformed),nuclear=localizeHexagram(rawNuclear);
 const sections=ichingEditorialSections(consultation,primary,transformed,nuclear,changingLines,verdict,counsel,resultCounsel,nuclearCounsel,language);
 const misc=ICHING_MISC_T[language]||ICHING_MISC_T.ES;
 const story=sections.map(item=>item.body),main=story.join(" "),rawCaution=(RAW_CAUTION_T[language]||RAW_CAUTION_T.ES)(hexagramRisk(primary.number,language)),rawAdvice=primary.number===transformed.number?counsel:`${counsel}${misc.thenOrient(resultCounsel)}`,caution=semanticOverlap(rawCaution,main)>.48?"":sentence(rawCaution),advice=semanticOverlap(rawAdvice,main)>.48||semanticOverlap(rawAdvice,caution)>.38?"":sentence(rawAdvice),sourceHexagramIds=unique([`hexagram:${primary.number}`,`hexagram:${nuclear.number}`,`hexagram:${transformed.number}`]),sourceLineIds=changingLines.map(number=>`line:${number}`),sourceConsultationIds=[`consultation:${consultation.id}`];
 const opening=seededChoice(`${consultation.id}:${primary.number}:${transformed.number}`,ICHING_OPENING_T[language]||ICHING_OPENING_T.ES),summary=`${consultation.id==="reasoned"?`${verdict}. `:""}${opening}: ${primary.name} ${misc.describesPresent}${changingLines.length?misc.changingSuffix(changingLines.join(", ")):misc.noMutation}${primary.number!==transformed.number?misc.orientedSuffix(transformed.name):""}. ${counsel}`;
 return {primary,transformed,nuclear,lines,changingLines,verdict,sections,story,summary,showWarning:Boolean(caution),warningTitle:misc.warningTitle,caution,showAdvice:Boolean(advice),adviceTitle:misc.adviceTitle,advice,narrativeSynthesis:{readingThesis:sections[0]?.body||"",mainMovement:sections.at(-1)?.body||"",sourceHexagramIds,sourceLineIds,sourceConsultationIds},debug:{primaryPattern,transformedPattern,nuclearPattern}};
}
